const listTrainingConversations = `-- name: ListTrainingConversations :many
SELECT c.id, c.project_id, c.user_id, c.title, c.mode, c.agent_id, c.model_selector, c.settings, c.compaction_head_message_seq, c.created_at, c.updated_at, c.archived_at FROM conversations c JOIN users u ON u.id = c.user_id
WHERE u.training_consent AND c.archived_at IS NULL
  AND (cardinality($1::text[]) = 0 OR c.mode = ANY($1::text[]))
  AND c.updated_at >= $2
ORDER BY c.created_at
LIMIT $3
`

type ListTrainingConversationsParams struct {
	Modes            []string  `json:"modes"`
	Since            time.Time `json:"since"`
	MaxConversations int32     `json:"max_conversations"`
}

// Conversations exportable into a dataset: the user opted in, the
// conversation is not archived, it is in one of the modes (an empty list
// takes every mode) and was last active since the cutoff.
func (q *Queries) ListTrainingConversations(ctx context.Context, arg ListTrainingConversationsParams) ([]Conversation, error) {
	rows, err := q.db.Query(ctx, listTrainingConversations, arg.Modes, arg.Since, arg.MaxConversations)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Conversation{}
	for rows.Next() {
		var i Conversation
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.UserID,
			&i.Title,
			&i.Mode,
			&i.AgentID,
			&i.ModelSelector,
			&i.Settings,
			&i.CompactionHeadMessageSeq,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

